package qynl.agent;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class OllamaBrain{private final QynlConfig c;public OllamaBrain(QynlConfig c){this.c=c;}public String think(String state,String goal){try{String p="Minecraft companion. Goal="+goal+" State="+state+". Return one action: follow,gather_wood,gather_stone,mine,eat,explore,attack,craft,build,return,wait,stop.";String body="{\"model\":\""+c.ollamaModel+"\",\"prompt\":\""+p.replace("\"","\\\"")+"\",\"stream\":false}";HttpRequest r=HttpRequest.newBuilder(URI.create(c.ollamaUrl+"/api/generate")).timeout(Duration.ofSeconds(8)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build();String x=HttpClient.newHttpClient().send(r,HttpResponse.BodyHandlers.ofString()).body();int i=x.indexOf("response");if(i<0)return "wait";int a=x.indexOf(':',i)+1,b=x.indexOf(',',a);if(b<0)b=x.lastIndexOf('}');return x.substring(a,b).replace("\"","").trim().toLowerCase();}catch(Exception e){return "wait";}}}
